## Type Conversion Challenge

```js
const result = parseInt('100px') + parseInt('12.7') + Number(true);
console.log(result);
```

### What will be the output?

## Shallow Copy Challenge

```js
const user = {
  name: 'Rahul',
  address: {
    city: 'Hyderabad'
  }
};

const copied = { ...user };
copied.address.city = 'Chennai';

console.log(user.address.city);
```

### What will be printed?

## String Methods Challenge

```js
let str = 'javaScript';
str = str.slice(0, 4).toUpperCase().replace('JAVA', 'Type');
const result = str.substring(-2, 4);
console.log(result);
```

### What will be printed?

## Array Methods Challenge

```js
const arr = [2, 3];
arr.push(4);
arr.unshift(1);
arr.shift();
const sliced = arr.slice(1);
sliced.splice(1, 1, 9, 10);
console.log(sliced);
```

### What will be the output?

## forEach vs map

```js
const arr = [1, 2, 3];
const result1 = arr.forEach(x => x * 2);
const result2 = arr.map(x => x * 2);
console.log(result1, result2);
```

### What will be printed?

## Array Rotation Challenge

```js
const arr = [1, 2, 3, 4, 5];
const k = 2;
const rotated = [...arr.slice(-k), ...arr.slice(0, -k)];
console.log(rotated);
```

### What will be the output?

## Predict the Output

```js
const user = {
  name: 'Kiran',
  age: 26,
  city: 'Pune'
};

const { name, age } = user;
console.log(name, age);
```

### What will be printed?

## Object Merge Challenge

```js
const obj1 = { a: 1, b: 2 };
const obj2 = { b: 3, c: 4 };
const merged = { ...obj1, ...obj2, z: 100 };
console.log(merged);
```

### What will be printed?

## Optional Chaining

```js
const obj = { a: { b: 2 } };
console.log(obj.a?.c?.d);
```

### What will be printed?

## Set Methods

```js
const set = new Set([1, 2, 2, 3]);
set.add(4);
set.delete(2);
console.log(set.size, set.has(2));
```

### What will be printed?

## Map Iteration

```js
const m = new Map();
m.set('a', 1);
m.set('b', 2);

for (const [k, v] of m) {
  console.log(k, v);
}
```

### What will be logged?

## Map Clear Challenge

```js
const m = new Map([
  ['x', 10],
  ['y', 20]
]);

m.clear();
console.log(m.size);
```

### What will be printed?

## `this` Keyword Challenge

```js
const user = {
  name: 'Ravi',
  greet: () => console.log(this.name)
};

user.greet();
```

### What is the best explanation?

## call, apply, bind

```js
const person = {
  name: 'Anu',
  greet: function(msg, sign) {
    return `${msg}, ${this.name}${sign}`;
  }
};

const other = { name: 'Vikram' };

console.log(person.greet.call(other, 'Hello', '!'));
console.log(person.greet.apply(other, ['Hi', '...']));

const bound = person.greet.bind(other, 'Hey');
console.log(bound('?'));
```

### What will be printed?

## Closure Challenge

```js
function outer() {
  let count = 0;
  return function inner() {
    count++;
    console.log(count);
  };
}

const fn1 = outer();
const fn2 = outer();

fn1();
fn1();
fn2();
```

### What will be printed?

## Async / Await Order

```js
async function test() {
  console.log('A');
  await Promise.resolve();
  console.log('B');
}

console.log('C');
test();
console.log('D');
```

### What will be printed?

## Event Loop Challenge

```js
console.log('Start');

Promise.resolve()
  .then(() => {
    console.log('Promise 1');
    return Promise.resolve('Promise 2');
  })
  .then(res => {
    console.log(res);
  });

setTimeout(() => {
  console.log('Timer');
}, 0);

console.log('End');
```

### What will be printed?

## Promise Chain

```js
Promise.resolve()
  .then(() => {
    console.log('First');
    return Promise.resolve('Second');
  })
  .then(msg => {
    console.log(msg);
  })
  .then(() => {
    console.log('Third');
  });
```

### What will be printed?

## Advanced Event Loop

```js
console.log('Start');

setTimeout(() => {
  console.log('Timeout 1');
}, 0);

Promise.resolve().then(() => {
  console.log('Promise 1');
  setTimeout(() => {
    console.log('Timeout 2');
  }, 0);
});

Promise.resolve().then(() => {
  console.log('Promise 2');
});

console.log('End');
```

### What will be printed?
